inline const LNE *GetLNE(const void *buf) {
  return ::flatbuffers::GetRoot<LNE>(buf);
}

inline const LNE *GetSizePrefixedLNE(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<LNE>(buf);
}

inline const char *LNEIdentifier() {
  return "$LNE";
}

inline bool LNEBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, LNEIdentifier());
}

inline bool SizePrefixedLNEBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, LNEIdentifier(), true);
}

template <bool B = false>
inline bool VerifyLNEBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<LNE>(LNEIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedLNEBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<LNE>(LNEIdentifier());
}

inline void FinishLNEBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<LNE> root) {
  fbb.Finish(root, LNEIdentifier());
}

inline void FinishSizePrefixedLNEBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<LNE> root) {
  fbb.FinishSizePrefixed(root, LNEIdentifier());
}

inline std::unique_ptr<LNET> UnPackLNE(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<LNET>(GetLNE(buf)->UnPack(res));
}

inline std::unique_ptr<LNET> UnPackSizePrefixedLNE(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<LNET>(GetSizePrefixedLNE(buf)->UnPack(res));
}

